/* Trigger structure for table `bet_prbal` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `bet_prbal_trigger` */$$

/*!50003 CREATE */ /*!50003 TRIGGER `bet_prbal_trigger` AFTER INSERT ON `bet_prbal` FOR EACH ROW BEGIN
  
	  IF NEW.company_amount = 0 THEN
		bet_balance, bet_win_balance, bet_loss_balance, bet_prof_balance, bet_cnt, bet_cnt_b, bet_cnt_p, bet_start, bet_end) 
	      VALUES (NEW.bet_mb_fid, NEW.bet_mb_uid, NEW.bet_table_code, NEW.bet_table_name, 
		IF(NEW.point_amount = 4  OR NEW.bet_mb_level = 1, 0, NEW.bet_money), 
		IF(NEW.point_amount = 4  OR NEW.bet_mb_level = 1, 0, NEW.bet_win_money), 
		IF(NEW.bet_win_money <> 0 OR NEW.bet_mb_level = 1, 0, NEW.bet_money),
		IF(NEW.bet_win_money = 0 OR NEW.bet_mb_level = 1, 0, NEW.bet_win_money-NEW.bet_money), 
		IF(NEW.point_amount = 4  OR NEW.bet_mb_level = 1, 0, NEW.bet_balance), 
		IF(NEW.point_amount = 4  OR NEW.bet_mb_level = 1, 0, NEW.bet_win_balance), 
		IF(NEW.bet_win_balance <> 0 OR NEW.bet_mb_level = 1, 0, NEW.bet_balance), 
		IF(NEW.bet_win_balance = 0 OR NEW.bet_mb_level = 1, 0, NEW.bet_win_balance-NEW.bet_balance), 
		1, IF(NEW.bet_balance > 0, 1, 0), IF(NEW.bet_money - NEW.bet_balance > 0, 1, 0),
		CONCAT(SUBSTR(NEW.bet_time, 1, 13),':00:00'), CONCAT(SUBSTR(NEW.bet_time, 1, 13),':59:59') )
	     ON DUPLICATE KEY UPDATE 
		bet_money = bet_money + IF(NEW.point_amount = 4 OR NEW.bet_mb_level = 1, 0, NEW.bet_money) , 
		bet_win_money = bet_win_money + IF(NEW.point_amount = 4 OR NEW.bet_mb_level = 1, 0, NEW.bet_win_money), 
		bet_loss_money = bet_loss_money + IF(NEW.bet_win_money <> 0 OR NEW.bet_mb_level = 1, 0, NEW.bet_money), 
		bet_prof_money = bet_prof_money + IF(NEW.bet_win_money = 0 OR NEW.bet_mb_level = 1, 0, NEW.bet_win_money-NEW.bet_money), 
		bet_balance = bet_balance + IF(NEW.point_amount = 4 OR NEW.bet_mb_level = 1, 0, NEW.bet_balance), 
		bet_win_balance = bet_win_balance + IF(NEW.point_amount = 4 OR NEW.bet_mb_level = 1, 0, NEW.bet_win_balance),
		bet_loss_balance = bet_loss_balance + IF(NEW.bet_win_balance <> 0 OR NEW.bet_mb_level = 1, 0, NEW.bet_balance), 
		bet_prof_balance = bet_prof_balance + IF(NEW.bet_win_balance = 0 OR NEW.bet_mb_level = 1, 0, NEW.bet_win_balance-NEW.bet_balance), 
		bet_cnt = bet_cnt + 1, bet_cnt_b = bet_cnt_b + IF(NEW.bet_balance > 0, 1, 0),
		bet_cnt_p = bet_cnt_p + IF(NEW.bet_money - NEW.bet_balance > 0, 1, 0);
	  ELSE
	    VALUES (NEW.bet_mb_fid, NEW.bet_mb_uid, NEW.bet_table_code, NEW.bet_table_name, NEW.bet_money, /*미처리금액*/ 1, /*미처리회수*/      
	      CONCAT(SUBSTR(NEW.bet_time, 1, 13),':00:00'), CONCAT(SUBSTR(NEW.bet_time, 1, 13),':59:59') )
	     ON DUPLICATE KEY UPDATE
	      bet_nproc_money = bet_nproc_money + NEW.bet_money,
	      bet_cnt_n = bet_cnt_n + 1; /*미처리회수*/
	      
	  END IF;
    END */$$


