/* Trigger structure for table `bet_prbal` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `bet_prbal_update_trigger` */$$

/*!50003 CREATE */ /*!50003 TRIGGER `bet_prbal_update_trigger` AFTER UPDATE ON `bet_prbal` FOR EACH ROW BEGIN
  IF OLD.company_amount > 0 AND OLD.employee_amount = 0 AND NEW.employee_amount = 1 THEN
    bet_proc_money, bet_proc_win, bet_cnt_y, bet_start, bet_end) 
    VALUES (NEW.bet_mb_fid, NEW.bet_mb_uid, NEW.bet_table_code, NEW.bet_table_name, 
      IF(NEW.point_amount = 4  OR NEW.bet_mb_level = 1, 0, NEW.bet_money),  /*배팅금*/
      IF(NEW.point_amount = 4  OR NEW.bet_mb_level = 1, 0, NEW.bet_win_money),  /*적중금*/
      IF(NEW.bet_win_money <> 0 OR NEW.bet_mb_level = 1, 0, NEW.bet_money), /*미적중금*/
      IF(NEW.bet_win_money = 0 OR NEW.bet_mb_level = 1, 0, NEW.bet_win_money-NEW.bet_money), /*당첨금*/
      IF(NEW.point_amount = 4  OR NEW.bet_mb_level = 1, 0, NEW.bet_money), /*처리금액*/
      IF(NEW.point_amount = 4  OR NEW.bet_mb_level = 1, 0, NEW.bet_win_money),  
      1, /*처리회수*/
      CONCAT(SUBSTR(NEW.bet_time, 1, 13),':00:00'), CONCAT(SUBSTR(NEW.bet_time, 1, 13),':59:59') )
     ON DUPLICATE KEY UPDATE
      bet_money = bet_money + IF(NEW.point_amount = 4 OR NEW.bet_mb_level = 1, 0, NEW.bet_money) , 
      bet_win_money = bet_win_money + IF(NEW.point_amount = 4 OR NEW.bet_mb_level = 1, 0, NEW.bet_win_money), 
      bet_loss_money = bet_loss_money + IF(NEW.bet_win_money <> 0 OR NEW.bet_mb_level = 1, 0, NEW.bet_money), 
      bet_prof_money = bet_prof_money + IF(NEW.bet_win_money = 0 OR NEW.bet_mb_level = 1, 0, NEW.bet_win_money-NEW.bet_money), 
      bet_nproc_money = bet_nproc_money - NEW.bet_money,
      bet_proc_money = bet_proc_money +  + IF(NEW.point_amount = 4 OR NEW.bet_mb_level = 1, 0, NEW.bet_money), /*배팅금액*/
      bet_proc_win = bet_proc_win + IF(NEW.point_amount = 4 OR NEW.bet_mb_level = 1, 0, NEW.bet_win_money), /*적중금액*/
      bet_cnt_n = bet_cnt_n - 1, /*미처리회수*/
      bet_cnt_y = bet_cnt_y + 1; /*처리회수*/
  ELSEIF OLD.company_amount > 0 AND OLD.employee_amount = 1 THEN
    VALUES (NEW.bet_mb_fid, NEW.bet_mb_uid, NEW.bet_table_code, NEW.bet_table_name, NEW.bet_money, /*처리금액*/
      NEW.bet_win_money,  1, /*처리회수*/
      CONCAT(SUBSTR(NEW.bet_time, 1, 13),':00:00'), CONCAT(SUBSTR(NEW.bet_time, 1, 13),':59:59') )
     ON DUPLICATE KEY UPDATE
      bet_proc_win = bet_proc_win + NEW.bet_win_money - OLD.bet_win_money; /*적중금액*/
  END IF;
    END */$$


