insert  into `conf_msg`(`conf_id`,`conf_memo`,`conf_content`,`conf_active`,`conf_update`) values (38,'일반답변안내','<p style=\"text-align: center;\"><span style=\"color: rgb(255, 255, 0); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 12px; font-weight: 700; background-color: rgb(0, 0, 0);\">안녕하세요. ATM입니다.</span></p><p style=\"text-align: center;\"><font color=\"#ffff00\" face=\"Helvetica Neue, Helvetica, Arial, sans-serif\"><span style=\"font-size: 12px; background-color: rgb(0, 0, 0);\"><span style=\"font-weight: 700;\">문의주신내용 답변드리겠습니다.</span></span></font></p><p style=\"text-align: center;\"><font color=\"#ffff00\" face=\"Helvetica Neue, Helvetica, Arial, sans-serif\"><span style=\"font-size: 12px; background-color: rgb(0, 0, 0);\"><span style=\"font-weight: 700;\"><br></span></span></font></p><p style=\"text-align: center;\"><span style=\"background-color: rgb(0, 0, 0); color: rgb(255, 255, 0); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 12px; font-weight: 700;\">▶</span><span style=\"background-color: rgb(0, 0, 0); color: rgb(255, 255, 0); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 12px; font-weight: 700;\">▶</span><span style=\"background-color: rgb(0, 0, 0); color: rgb(255, 255, 0); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 12px; font-weight: 700;\">▶대략적인 입금액을 말씀부탁드립니다.</span></p><p style=\"text-align: center;\"><span style=\"background-color: rgb(0, 0, 0); color: rgb(255, 255, 0); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 12px; font-weight: 700;\"><br></span></p><p style=\"text-align: center;\"><span style=\"font-weight: 700; color: rgb(255, 255, 0); background-color: rgb(0, 0, 0); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 12px;\">오늘도 저희 ATM을 이용해 주셔서 진심으로 감사드리며,&nbsp;</span></p><p style=\"font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 12px; text-align: center;\"><span style=\"background-color: rgb(0, 0, 0);\"><font color=\"#ffff00\"><span style=\"font-weight: 700;\">즐기시는 동안 좋은 성과 거두시길 바랍니다.</span></font></span></p>',1,'2024-03-07 13:10:57');
