insert  into `conf_site`(`conf_id`,`conf_memo`,`conf_content`,`conf_content_cn`,`conf_active`,`conf_update`,`conf_idx`) values (9,'계좌문의매크로','<p><b>	안녕하세요 운영진 입니다.</b></p><p><b>▷&nbsp; 계좌문의는 1:1 고객센터로 문의 바랍니다&nbsp;</b></p><p><b>\n▷선 입금후 충전 신청 해주시면 빠른 처리가 되며, 수표 입금시 \n   충전 및 환전은 절대 불가능 하니 꼭 숙지 하시기 바랍니다. </b></p><p><b>\n   (타인명의로 입금할시 고객센터 문의후 진행 바랍니다.)	</b></p><p><b>\n   고객센터 문의 없이 이름을 변경하여 입금시 충전 처리를 해드리지 않으며\n   반환되어 집니다.</b></p><p><b><br></b></p>','<p><span style=\"background-color: rgb(255, 0, 255);\">szxvwefszdfdxv</span></p>',0,'2022-03-01 00:00:00','0');
insert  into `conf_site`(`conf_id`,`conf_memo`,`conf_content`,`conf_content_cn`,`conf_active`,`conf_update`,`conf_idx`) values (10,'사이트점검','    -점검 내용-\n안녕하세요 ATM입니다.\n디도스공격으로 인한 긴급점검을 진행합니다.\n갑작스러운 점검 양해부탁드립니다.\n\n완료되는 즉시 공지토록하겠습니다.','',0,'2022-03-01 00:00:00','0');
